// The gatekeeper — one code node instead of $10 a seat.
// Free slot → book it, write a real calendar invite. Taken → say so.
const fs = require('fs');
const path = require('path');
const base = $env.EP06_DIR;
const file = path.join(base, 'data', 'bookings.csv');
const HOURS = ['09:00', '10:00', '11:00', '13:00', '14:00', '15:00'];

const b = $input.first().json;
const name = b.Name;
const email = b.Email;
const time = b.Time;
const date = String(b.Date).slice(0, 10);

const rows = fs.readFileSync(file, 'utf8').trim().split('\n').slice(1).map((l) => l.split(','));
const taken = rows.some(([d, t]) => d === date && t === time);

if (!HOURS.includes(time)) {
  return [{ json: { title: 'Outside working hours', message: 'Pick a time between 09:00 and 15:00.' } }];
}
if (taken) {
  return [{ json: { title: 'That slot is already taken', message: date + ' at ' + time + ' is booked — go back and pick another slot.' } }];
}

const raw = fs.readFileSync(file, 'utf8');
fs.writeFileSync(file, raw.trimEnd() + '\n' + [date, time, name, email].join(',') + '\n');

const outDir = path.join(base, 'out');
fs.mkdirSync(outDir, { recursive: true });
const dt = date.replace(/-/g, '') + 'T' + time.replace(':', '') + '00';
const ics = [
  'BEGIN:VCALENDAR', 'VERSION:2.0', 'PRODID:-//ships itself//booking//EN',
  'BEGIN:VEVENT', 'UID:' + Date.now() + '@shipsitself', 'DTSTART:' + dt,
  'DURATION:PT30M', 'SUMMARY:Call \u2014 ' + name,
  'DESCRIPTION:Booked via the zero-dollar page', 'END:VEVENT', 'END:VCALENDAR',
].join('\r\n');
fs.writeFileSync(path.join(outDir, 'booking-' + date + '-' + time.replace(':', '') + '.ics'), ics);

return [{ json: { title: 'Booked: ' + date + ' at ' + time, message: 'Calendar invite written. See you there, ' + name + '.' } }];
